struct LazyUpdateTree {
	using V = int;
	using U = int;
	const V id = INT_MIN;
	const V def = 0;
	const U idU = 0;
	V binop(V a, V b) { return max(a, b); }
	V applyUpdate(U u, V v) { return v + u; }
	U mergeUpdate(U oldU, U nw) { return oldU + nw; }
	vector<V> arr;
	vector<U> lazy;
	int size;
	LazyUpdateTree(int n) :
		arr(4 * n + 2, def), lazy(4 * n + 2, idU), size(n) {}
	void updateNode(int cur, int, int, U u) {
		lazy[cur] = mergeUpdate(lazy[cur], u);
		arr[cur] = applyUpdate(u, arr[cur]);
	}
	void push(int cur, int l, int r) {
		int mid = l + (r - l) / 2;
		updateNode(2 * cur, l, mid, lazy[cur]);
		updateNode(2 * cur + 1, mid + 1, r, lazy[cur]);
		lazy[cur] = idU;
	}
	void update(int cur, int l, int r, int ql, int qr, U u) {
		if (qr < l || r < ql) return;
		if (ql <= l && r <= qr) {
			updateNode(cur, l, r, u); return;
		}
		push(cur, l, r);
		int mid = l + (r - l) / 2;
		update(2 * cur, l, mid, ql, qr, u);
		update(2 * cur + 1, mid + 1, r, ql, qr, u);
		arr[cur] = binop(arr[2 * cur], arr[2 * cur + 1]);
	}
	void update(int ql, int qr, U u) {
		if (ql > qr) return;
		update(1, 0, size - 1, ql, qr, u);
	}
	V query(int cur, int l, int r, int ql, int qr) {
		if (qr < l || r < ql) return id;
		if (ql <= l && r <= qr) return arr[cur];
		push(cur, l, r);
		int mid = l + (r - l) / 2;
		return binop(query(2 * cur, l, mid, ql, qr),
			query(2 * cur + 1, mid + 1, r, ql, qr));
	}
	V query(int ql, int qr) {
		if (ql > qr) return id;
		return query(1, 0, size - 1, ql, qr);
	}
};

struct LiChao {
	struct Fn {
		ll a, b;
		Fn(ll a = 0, ll b = 0) : a(a), b(b) {}
		ll operator()(ll x) const { return a * x + b; }
	};
	static const ll INF = LLONG_MAX / 4;
	struct Node {
		Fn f{0, INF};
		Node *l = 0, *r = 0;
	};
	Node *root = new Node();
	int L, R;
	LiChao(int L, int R) : L(L), R(R) {}
	void insert(Fn nw, Node *n, int l, int r) {
		if (!n) return;
		int m = l + (r - l) / 2;
		bool lef = nw(l) < n->f(l);
		bool mid = nw(m) < n->f(m);
		if (mid) swap(nw, n->f);
		if (l == r - 1) return;
		Node *&ch = lef != mid ? n->l : n->r;
		if (!ch) ch = new Node();
		insert(nw, ch, lef != mid ? l : m,
			lef != mid ? m : r);
	}
	void insert(Fn nw) { insert(nw, root, L, R); }
	ll query(int x, Node *n, int l, int r) {
		if (!n || l > x || r <= x) return INF;
		int m = l + (r - l) / 2;
		ll res = n->f(x);
		return x < m ? min(res, query(x, n->l, l, m))
			: min(res, query(x, n->r, m, r));
	}
	ll query(int x) { return query(x, root, L, R); }
};

struct Line {
	mutable ll k, m, p;
	bool operator<(const Line& o) const { return k < o.k; }
	bool operator<(ll x) const { return p < x; }
};

struct LineContainer : multiset<Line, less<>> {
	// (for doubles, use inf = 1/.0, div(a,b) = a/b)
	static const ll inf = LLONG_MAX;
	ll div(ll a, ll b) { // floored division
		return a / b - ((a ^ b) < 0 && a % b); }
	bool isect(iterator x, iterator y) {
		if (y == end()) return x->p = inf, 0;
		if (x->k == y->k) x->p = x->m > y->m ? inf : -inf;
		else x->p = div(y->m - x->m, x->k - y->k);
		return x->p >= y->p;
	}
	void add(ll k, ll m) {
		auto z = insert({k, m, 0}), y = z++, x = y;
		while (isect(y, z)) z = erase(z);
		if (x != begin() && isect(--x, y)) isect(x, y = erase(y));
		while ((y = x) != begin() && (--x)->p >= y->p)
			isect(x, erase(y));
	}
	ll query(ll x) {
		assert(!empty());
		auto l = *lower_bound(x);
		return l.k * x + l.m;
	}
};

template<class T, int N> struct Matrix {
	typedef Matrix M;
	array<array<T, N>, N> d{};
	M operator*(const M& m) const {
		M a;
		rep(i,0,N) rep(j,0,N)
			rep(k,0,N) a.d[i][k] += d[i][j] * m.d[j][k];
		return a;
	}
	array<T, N> operator*(const array<T, N>& vec) const {
		array<T, N> ret{};
		rep(i,0,N) rep(j,0,N) ret[i] += d[i][j] * vec[j];
		return ret;
	}
	M operator^(ll p) const {
		assert(p >= 0);
		M a, b(*this);
		rep(i,0,N) a.d[i][i] = 1;
		while (p) {
			if (p&1) a = a*b;
			b = b*b;
			p >>= 1;
		}
		return a;
	}
};

